#!/usr/bin/env python3
import types,sys,os,json,csv,sqlite3
from pathlib import Path
previous={}
try:
    previous['research_stream_artifact']=sys.modules.get('research_stream_artifact')
    module=types.ModuleType('research_stream_artifact');sys.modules['research_stream_artifact']=module
    exec(compile(bytes.fromhex(""),'bundled-research_stream_artifact',"exec"),module.__dict__)
    previous['research_design']=sys.modules.get('research_design')
    module=types.ModuleType('research_design');sys.modules['research_design']=module
    exec(compile(bytes.fromhex(""),'bundled-research_design',"exec"),module.__dict__)
    stream=sys.modules["research_stream_artifact"]
    component=types.ModuleType("c_safety");component._EMBEDDED_IDS={'component_sha256': '7c0e33b7e095bbe9a353de353363fd8dd984854ba8243c39ed9d13e0c7225fac', 'stream_support_sha256': '0b5d218f7120dc897d2daa0acb801a95527e70e61fd58fd1a4788761c0189b13', 'design_reader_sha256': 'f18399f81180d8d3637b03eb5f4a7369b5a05a6e31909d50375538006d329f14'}
    exec(compile(bytes.fromhex(""),"bundled-c-safety","exec"),component.__dict__)
finally:
    for name,old in previous.items():
        if old is None:sys.modules.pop(name,None)
        else:sys.modules[name]=old
FIXED_INPUTS=('design', 'candidates', 'scopes', 'evidence')
FIXED_SCHEMA=1

def run():
    expected_inputs = ['AUTONOMICS_INPUT'+str(i) for i in range(len(FIXED_INPUTS)+1)]
    actual_inputs = [k for k in os.environ if k.startswith('AUTONOMICS_INPUT') and k[len('AUTONOMICS_INPUT'):].isdigit()]
    component.require(set(actual_inputs) == set(expected_inputs), 'all and only fixed risk input ports required')
    expected_outputs = ['AUTONOMICS_OUTPUT'+str(i) for i in range(5)]
    actual_outputs = [k for k in os.environ if k.startswith('AUTONOMICS_OUTPUT') and k[len('AUTONOMICS_OUTPUT'):].isdigit()]
    component.require(set(actual_outputs) == set(expected_outputs), 'all and only fixed risk output ports required')
    inputs = [Path(os.environ[k]) for k in expected_inputs]
    outputs = [Path(os.environ['AUTONOMICS_OUTPUT'+str(i)]) for i in range(5)]
    component.require([p.name for p in outputs] ==
        ['candidate-register.tsv','candidate-scopes.tsv','risk-evidence.tsv','risk-matrix.tsv','risk-audit.json'],
        'exact fixed risk output ports required')
    parent = outputs[0].parent.absolute()
    component.require(parent != Path('/') and len({p.parent.absolute() for p in outputs}) == 1 and
        all(p.is_absolute() and '..' not in p.parts for p in outputs), 'absolute private risk output ports required')
    component.require(not any(os.path.lexists(p) for p in outputs) and
        not any(p.is_symlink() for p in [parent,*parent.parents]), 'existing or symlink output refused')
    config,_,policy = component.declaration(inputs[0])
    component.require(config['schema_version'] == FIXED_SCHEMA, 'fixed versioned risk entry differs')
    actual = stream.apply_process_memory_limit(policy)
    parent.mkdir(parents=True,exist_ok=True)
    bundle = parent / '.c-safety-complete'
    component.require(not os.path.lexists(bundle), 'complete risk bundle exists')
    audit = component.matrix(inputs[0],dict(zip(FIXED_INPUTS,inputs[1:])),bundle)
    for target in outputs:
        os.link(bundle/target.name,target)
    print(json.dumps({'status':audit['status'],'counts':audit['counts'],
        'source_RLIMIT_AS_bytes':actual,'formal_authorized':False}))
if __name__ == '__main__':
    try: run()
    except (ValueError,KeyError,TypeError,OSError,UnicodeError,csv.Error,sqlite3.Error,MemoryError) as error:
        print('BLOCKED: '+str(error),file=sys.stderr)
        raise SystemExit(2)
